    /**
     * File icons with a short format label.
     */
    private const LABELLED = [
        'file-word' => 'DOC',
        'file-excel' => 'XLS',
        'file-ppt' => 'PPT',
        'file-csv' => 'CSV',
        'file-pdf' => 'PDF',
    ];

    public function __construct(public string $name, public float $stroke = 1.75) {}

    public function render(): string
    {
        if (isset(self::LABELLED[$this->name])) {
            $body = '<path d="M15 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V7Z"/><path d="M14 2v4a2 2 0 0 0 2 2h4"/>'
                .'<text x="12" y="17.2" text-anchor="middle" font-size="5.6" font-weight="800" font-family="Inter Variable, Arial, sans-serif" fill="currentColor" stroke="none" letter-spacing="-.2">'
                .self::LABELLED[$this->name].'</text>';
        } else {
            $body = self::ICONS[$this->name] ?? self::FILE;
        }

        return '<svg {{ $attributes->merge(["class" => "size-5"]) }} xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="'.$this->stroke.'" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'.$body.'</svg>';
    }

    public static function exists(string $name): bool
    {
        return isset(self::ICONS[$name]) || isset(self::LABELLED[$name]);
    }
